class Solution:
    def filterIntervals(self, occupiedIntervals: List[List[int]], freeStart: int, freeEnd: int) -> List[List[int]]:
        ivs = sorted(occupiedIntervals)
        merged = []
        cs, ce = ivs[0]
        for s, e in ivs[1:]:
            if s <= ce + 1:
                ce = max(ce, e)
            else:
                merged.append([cs, ce])
                cs, ce = s, e
        merged.append([cs, ce])
        res = []
        for s, e in merged:
            if e < freeStart or s > freeEnd:
                res.append([s, e])
                continue
            if s < freeStart:
                res.append([s, freeStart - 1])
            if e > freeEnd:
                res.append([freeEnd + 1, e])
        return res

