class Solution {
public:
    vector<vector<int>> filterIntervals(vector<vector<int>>& occupiedIntervals, int freeStart, int freeEnd) {
        sort(occupiedIntervals.begin(), occupiedIntervals.end());
        vector<vector<int>> merged;
        long long cs = occupiedIntervals[0][0], ce = occupiedIntervals[0][1];
        for (int i = 1; i < (int)occupiedIntervals.size(); i++) {
            long long s = occupiedIntervals[i][0], e = occupiedIntervals[i][1];
            if (s <= ce + 1) ce = max(ce, e);
            else { merged.push_back({(int)cs, (int)ce}); cs = s; ce = e; }
        }
        merged.push_back({(int)cs, (int)ce});
        vector<vector<int>> res;
        for (auto& iv : merged) {
            long long s = iv[0], e = iv[1];
            if (e < freeStart || s > freeEnd) { res.push_back(iv); continue; }
            if (s < freeStart) res.push_back({(int)s, freeStart - 1});
            if (e > freeEnd) res.push_back({freeEnd + 1, (int)e});
        }
        return res;
    }
};

