class Solution {
    public int[][] filterIntervals(int[][] occupiedIntervals, int freeStart, int freeEnd) {
        Arrays.sort(occupiedIntervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        long cs = occupiedIntervals[0][0], ce = occupiedIntervals[0][1];
        for (int i = 1; i < occupiedIntervals.length; i++) {
            long s = occupiedIntervals[i][0], e = occupiedIntervals[i][1];
            if (s <= ce + 1) ce = Math.max(ce, e);
            else { merged.add(new int[]{(int)cs, (int)ce}); cs = s; ce = e; }
        }
        merged.add(new int[]{(int)cs, (int)ce});
        List<int[]> res = new ArrayList<>();
        for (int[] iv : merged) {
            long s = iv[0], e = iv[1];
            if (e < freeStart || s > freeEnd) { res.add(iv); continue; }
            if (s < freeStart) res.add(new int[]{(int)s, freeStart - 1});
            if (e > freeEnd) res.add(new int[]{freeEnd + 1, (int)e});
        }
        return res.toArray(new int[0][]);
    }
}

