var filterIntervals = function(occupiedIntervals, freeStart, freeEnd) {
    const ivs = [...occupiedIntervals].sort((a, b) => a[0] - b[0]);
    const merged = [];
    let cs = ivs[0][0], ce = ivs[0][1];
    for (let i = 1; i < ivs.length; i++) {
        const [s, e] = ivs[i];
        if (s <= ce + 1) ce = Math.max(ce, e);
        else { merged.push([cs, ce]); cs = s; ce = e; }
    }
    merged.push([cs, ce]);
    const res = [];
    for (const [s, e] of merged) {
        if (e < freeStart || s > freeEnd) { res.push([s, e]); continue; }
        if (s < freeStart) res.push([s, freeStart - 1]);
        if (e > freeEnd) res.push([freeEnd + 1, e]);
    }
    return res;
};
